{"app.loglevel":{"type":"keyword","script":{"source":"def n = doc['app.severity'].value;
if (n == 0) { emit("0. Emergency"); }
else if (n == 1) { emit("1. Alert"); }
else if (n == 2) { emit("2. Critical"); }
else if (n == 3) { emit("3. Error"); }
else if (n == 4) { emit("4. Warning"); }
else if (n == 5) { emit("5. Notice"); }
else if (n == 6) { emit("6. Informational"); }
else if (n == 7) { emit("7. Debug"); }
else { emit(""); }"}}}
